@php($editing=isset($cargo))<div class="row g-3">@unless($editing)<div class="col-md-4"><label class="form-label">Número de cargo</label><input class="form-control" name="numero_cargo" maxlength="40" required></div><div class="col-md-4"><label class="form-label">Cliente</label><select class="form-select" name="cliente_id" required><option value="">Seleccione</option>@foreach($clientes as $c)<option value="{{ $c->id }}">{{ $c->numero_socio }} · {{ $c->nombre }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Membresía relacionada</label><select class="form-select" name="membresia_id"><option value="">Ninguna</option>@foreach($membresias as $m)<option value="{{ $m->id }}">#{{ $m->id }} · {{ $m->tipo }} · {{ $m->fecha_inicio }}</option>@endforeach</select></div><div class="col-md-4"><label class="form-label">Estado inicial</label><select class="form-select" name="estado_cargo_cobro_id">@foreach($estados as $e)@if(!$e->es_terminal)<option value="{{ $e->id }}">{{ $e->nombre }}</option>@endif @endforeach</select></div>@endunless<div class="col-md-8"><label class="form-label">Concepto</label><input class="form-control" name="concepto" maxlength="150" value="{{ old('concepto',$cargo->concepto??'') }}" required></div><div class="col-12"><label class="form-label">Descripción</label><textarea class="form-control" name="descripcion">{{ old('descripcion',$cargo->descripcion??'') }}</textarea></div>@foreach(['subtotal'=>'Subtotal','descuento'=>'Descuento','impuesto'=>'Impuesto'] as $f=>$l)<div class="col-md-3"><label class="form-label">{{ $l }}</label><input type="number" step="0.01" min="0" class="form-control" name="{{ $f }}" value="{{ old($f,$cargo?->{$f}??($f==='subtotal'?'':0)) }}" required></div>@endforeach @unless($editing)<div class="col-md-3"><label class="form-label">Moneda</label><input class="form-control text-uppercase" name="moneda" value="HNL" maxlength="3" required></div>@endunless<div class="col-md-3"><label class="form-label">Vencimiento</label><input type="date" class="form-control" name="fecha_vencimiento" value="{{ old('fecha_vencimiento',$cargo->fecha_vencimiento??'') }}"></div></div>
